# S0《地图工程》原文的 16 个纵轴节点（含区间节点“1524—1527”）
MAP_AXIS_YEARS = [1270, 1272, 1300, 1356, 1450, "1524—1527", 1618, 1648,
                  1789, 1815, 1848, 1866, 1871, 1918, 1945, 1960]

# 区间节点 -> 代表年份（用于与事件表对齐）
MAP_AXIS_RANGE_START = {"1524—1527": 1524}


def map_axis_node_keys():
    """返回 S0 地图纵轴 16 节点对应的整数年份集合"""
    out = set()
    for y in MAP_AXIS_YEARS:
        if isinstance(y, int):
            out.add(y)
        else:
            out.add(MAP_AXIS_RANGE_START[y])
    return out

